// ============================================================
// NORMALIZAR v2 — Code Node (n8n)
// Projeto Tozi Imobiliária
// Recebe webhook bruto do SPX, classifica e padroniza
// ============================================================

const body = $input.first().json.body;

// ------------------------------------------------------------
// 1. DETECTAR FORMATO DO WEBHOOK
// ------------------------------------------------------------

const evento_original = body.event || body.conversation?.event || 'desconhecido';
const is_status_changed = evento_original === 'conversation_status_changed';

// ------------------------------------------------------------
// 2. EXTRAIR DADOS BRUTOS
// ------------------------------------------------------------

let conversa, contato_id, inbox_id, nome_cliente, nome_atendente;
let content, content_type, content_attrs, attachments;
let message_type, sender_type, sender_id, privado, mensagem_id, timestamp;
let status_conversa, labels, custom_attrs, em_atendimento;
let team_id;

if (is_status_changed) {
  // Formato 2 — conversation_status_changed
  conversa        = body;
  conversa_id     = body.id;
  inbox_id        = body.inbox_id;
  status_conversa = body.status;
  labels          = body.labels || [];
  custom_attrs    = body.custom_attributes || {};
  em_atendimento  = custom_attrs.atendimento === true;
  timestamp       = body.timestamp;
  team_id         = body.meta?.team?.id || null;

  contato_id      = body.contact_inbox?.contact_id || null;
  nome_cliente    = body.meta?.sender?.name || '';
  nome_atendente  = body.meta?.assignee?.name || null;

  const last_msg  = body.messages?.[0] || null;
  mensagem_id     = last_msg?.id || null;
  content         = last_msg?.content || null;
  content_type    = last_msg?.content_type || 'text';
  content_attrs   = last_msg?.content_attributes || {};
  attachments     = last_msg?.attachments || [];
  message_type    = last_msg?.message_type ?? null;
  sender_type     = last_msg?.sender_type?.toLowerCase() || null;
  sender_id       = last_msg?.sender_id || null;
  privado         = last_msg?.private || false;

} else {
  // Formato 1 — message_created (e outros eventos de mensagem)
  conversa_id     = body.conversation?.id;
  inbox_id        = body.inbox?.id || body.conversation?.inbox_id;
  status_conversa = body.conversation?.status || 'open';
  labels          = body.conversation?.labels || [];
  custom_attrs    = body.conversation?.custom_attributes || {};
  em_atendimento  = custom_attrs.atendimento === true;
  timestamp       = body.conversation?.timestamp || body.created_at;
  team_id         = body.conversation?.meta?.team?.id || null;

  contato_id      = body.conversation?.contact_inbox?.contact_id || null;
  nome_cliente    = body.conversation?.meta?.sender?.name || '';
  nome_atendente  = body.conversation?.meta?.assignee?.name || null;

  mensagem_id     = body.id;
  content         = body.content;
  content_type    = body.content_type || 'text';
  content_attrs   = body.content_attributes || {};
  privado         = body.private === true;

  // Attachments: podem vir no nível raiz ou dentro de messages
  attachments     = body.attachments
                    || body.conversation?.messages?.[0]?.attachments
                    || [];

  // sender_type: detectar tipo do remetente
  // Contact NÃO tem campo "type" no nível raiz, mas tem phone_number/identifier
  // User tem type: "user", AgentBot tem type: "agent_bot"
  const raw_sender_type = body.sender?.type || '';
  if (raw_sender_type) {
    sender_type = raw_sender_type.toLowerCase().replace('::', '_');
  } else if (body.sender?.phone_number || body.sender?.identifier) {
    sender_type = 'contact';
  } else if (body.message_type === 'incoming') {
    sender_type = 'contact';
  } else {
    sender_type = '';
  }
  sender_id = body.sender?.id || null;

  // message_type: webhook traz como string
  const mt_str = body.message_type;
  message_type = mt_str === 'incoming' ? 0
               : mt_str === 'outgoing' ? 1
               : mt_str === 'activity' ? 2
               : (typeof mt_str === 'number' ? mt_str : null);
}

// ------------------------------------------------------------
// 3. CLASSIFICAR AUTOR
// ------------------------------------------------------------

let autor;

if (message_type === 2) {
  autor = 'sistema';
} else if (sender_type === 'agent_bot') {
  autor = privado ? 'bot_nota' : 'clara';
} else if (sender_type === 'contact') {
  autor = 'cliente';
} else if (sender_type === 'user') {
  autor = 'atendente';
} else if (sender_id === null && sender_type === null) {
  autor = 'sistema';
} else {
  autor = 'desconhecido';
}

// ------------------------------------------------------------
// 4. CLASSIFICAR TIPO DE CONTEÚDO
// ------------------------------------------------------------

const attachment = (Array.isArray(attachments) && attachments.length > 0)
  ? attachments[0]
  : null;

let tipo_conteudo;
let midia = null;

if (attachment) {
  const ft = (attachment.file_type || '').toLowerCase();
  const tipo_map = {
    'image': 'imagem',
    'audio': 'audio',
    'video': 'video',
    'file': 'documento',
    'location': 'localizacao',
    'sticker': 'sticker',
    'contact': 'contato',
  };
  tipo_conteudo = tipo_map[ft] || 'documento';

  midia = {
    tipo: ft,
    url: attachment.data_url || null,
    thumb_url: attachment.thumb_url || null,
    file_size: attachment.file_size || null,
    file_name: attachment.extension
      ? `${attachment.message_id || 'file'}.${attachment.extension}`
      : (attachment.data_url?.split('/')?.pop() || null),
    width: attachment.width || null,
    height: attachment.height || null,
    // Dados extras para contato compartilhado
    fallback_title: attachment.fallback_title || null,
    meta: attachment.meta || null,
  };
} else if (content && content.trim() !== '') {
  tipo_conteudo = 'texto';
} else {
  tipo_conteudo = 'sem_conteudo';
}

// ------------------------------------------------------------
// 5. GERAR texto_humano
// ------------------------------------------------------------

const autor_legivel = autor === 'cliente' ? 'cliente'
                    : autor === 'atendente' ? 'atendente'
                    : autor === 'clara' ? 'assistente'
                    : 'remetente';

// Legenda: quando tem attachment + content, o content é a legenda
// Exceção: contato compartilhado — content é o nome do contato, não legenda
const legenda = (attachment && content && content.trim() && tipo_conteudo !== 'contato') ? content.trim() : null;

// Contato compartilhado: extrair nome e telefone do attachment
let contato_info = `[Contato compartilhado pelo ${autor_legivel}]`;
if (midia?.tipo === 'contact') {
  const nome_contato = [midia.meta?.firstName, midia.meta?.lastName].filter(Boolean).join(' ') || null;
  const tel_contato = midia.fallback_title || null;
  if (nome_contato && tel_contato) {
    contato_info = `[Contato compartilhado pelo ${autor_legivel}: ${nome_contato} — ${tel_contato}]`;
  } else if (nome_contato) {
    contato_info = `[Contato compartilhado pelo ${autor_legivel}: ${nome_contato}]`;
  } else if (tel_contato) {
    contato_info = `[Contato compartilhado pelo ${autor_legivel}: ${tel_contato}]`;
  }
}

const texto_humano_base = {
  'texto': content || '',
  'imagem': `[Imagem enviada pelo ${autor_legivel}]`,
  'audio': `[Áudio enviado pelo ${autor_legivel}]`,
  'video': `[Vídeo enviado pelo ${autor_legivel}]`,
  'localizacao': `[Localização compartilhada pelo ${autor_legivel}]`,
  'documento': `[Documento${midia?.file_name ? ': ' + midia.file_name : ''} enviado pelo ${autor_legivel}]`,
  'sticker': '[Figurinha]',
  'contato': contato_info,
  'sem_conteudo': '[Mensagem sem conteúdo]',
};

const base = texto_humano_base[tipo_conteudo] || '[Mensagem não identificada]';
const texto_humano = legenda ? `${base}\nLegenda: ${legenda}` : base;

// ------------------------------------------------------------
// 6. DETERMINAR TIPO DE EVENTO
// ------------------------------------------------------------

let tipo_evento;

if (is_status_changed) {
  tipo_evento = 'status_changed';
} else if (content_attrs?.nps_survey === true) {
  tipo_evento = 'nps';
} else {
  tipo_evento = 'mensagem';
}

// ------------------------------------------------------------
// 7. ROTEAMENTO
// ------------------------------------------------------------

let rota = 'ignorar';
let rota_final = 'ignorar';
let motivo_rota = '';

const tipos_midia_processavel = ['imagem', 'audio', 'video', 'documento', 'localizacao', 'contato'];

// Auxiliares para detecção de NPS
const texto_limpo = (content || '').trim();
const eh_numero_nps = /^(10|[0-9])$/.test(texto_limpo);
const tem_team = team_id != null;

// REGRA 0 — Status changed
if (is_status_changed) {
  if (status_conversa === 'resolved') {
    rota = 'limpar';
    rota_final = 'limpar';
    motivo_rota = 'Conversa resolvida';
  } else {
    rota = 'ignorar';
    rota_final = 'ignorar';
    motivo_rota = `Status changed não-resolved: ${status_conversa}`;
  }
}

// REGRA 1 — Activity
else if (message_type === 2) {
  rota = 'ignorar';
  rota_final = 'ignorar';
  motivo_rota = 'Mensagem de sistema (activity)';
}

// REGRA 2 — NPS (mensagem de saída com nps_survey)
else if (content_attrs?.nps_survey === true) {
  rota = 'ignorar';
  rota_final = 'ignorar';
  motivo_rota = 'Pesquisa NPS automática';
}

// REGRA 3 — AgentBot
else if (sender_type === 'agent_bot') {
  rota = 'ignorar';
  rota_final = 'ignorar';
  motivo_rota = 'Mensagem do bot (Clara/sistema)';
}

// REGRA 4 — Provável resposta de NPS
else if (autor === 'cliente' && status_conversa === 'resolved' && eh_numero_nps && tem_team) {
  rota = 'ignorar';
  rota_final = 'ignorar';
  motivo_rota = 'Provável resposta de NPS (número 0-10 em conversa resolvida com time atribuído)';
}

// REGRA 5 — Cliente (Contact)
else if (autor === 'cliente') {
  if (em_atendimento) {
    rota = 'ignorar';
    rota_final = 'ignorar';
    motivo_rota = 'Cliente em atendimento humano';
  } else if (tipos_midia_processavel.includes(tipo_conteudo)) {
    rota = 'midia';
    rota_final = 'clara';
    motivo_rota = `Mídia do cliente (${tipo_conteudo}) para processamento → Clara`;
  } else {
    rota = 'clara';
    rota_final = 'clara';
    motivo_rota = tipo_conteudo === 'texto'
      ? 'Mensagem de texto do cliente'
      : `Conteúdo não-processável do cliente (${tipo_conteudo})`;
  }
}

// REGRA 6 — Atendente (User)
else if (autor === 'atendente') {
  if (privado) {
    const conteudo_lower = (content || '').toLowerCase();
    if (conteudo_lower.includes('#tozi')) {
      rota = 'copiloto';
      rota_final = 'copiloto';
      motivo_rota = 'Chamada ao copiloto via #tozi';
    } else {
      rota = 'ignorar';
      rota_final = 'ignorar';
      motivo_rota = 'Nota privada sem menção ao copiloto';
    }
  } else {
    // Público
    if (tipos_midia_processavel.includes(tipo_conteudo)) {
      rota = 'midia';
      rota_final = 'marcar';
      motivo_rota = `Mídia do atendente (${tipo_conteudo}) para processamento → Marcar atendimento`;
    } else {
      rota = 'marcar';
      rota_final = 'marcar';
      motivo_rota = 'Atendente respondeu publicamente';
    }
  }
}

// REGRA 7 — Fallback
else {
  rota = 'ignorar';
  rota_final = 'ignorar';
  motivo_rota = `Caso não mapeado: autor=${autor}, sender_type=${sender_type}`;
}

// ------------------------------------------------------------
// 8. LIMPEZA DO #tozi (Copiloto)
// ------------------------------------------------------------

let texto = content || null;

if (rota === 'copiloto' && texto) {
  texto = texto
    .replace(/#tozi/gi, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// ------------------------------------------------------------
// 9. MONTAR SAÍDA
// ------------------------------------------------------------

return {
  json: {
    // Roteamento
    rota,
    rota_final,
    motivo_rota,

    // Identificação
    conversa_id,
    contato_id,
    inbox_id,
    sender_id,
    mensagem_id,

    // Classificação
    autor,
    tipo_conteudo,
    tipo_evento,

    // Conteúdo
    texto,
    texto_humano,
    legenda,

    // Mídia
    midia,

    // Contexto
    em_atendimento,
    privado,
    nome_cliente,
    nome_atendente,
    labels,
    status_conversa,
    team_id,
    custom_attributes: custom_attrs,

    // Meta
    timestamp,
    evento_original,
  }
};

// =============================
// FORMATAR HISTÓRICO (rápido)
// =============================
const response = $input.first().json;
const messages = response.payload ?? [];

// filtra activity e mensagens vazias
const relevantes = [];
for (const m of messages) {
  if (m?.message_type === 2) continue; // activity
  const c = (m?.content ?? '').trim();
  // mantém mesmo se vazio? aqui descarta vazio total
  if (!c && !(m?.attachments?.length)) continue;
  relevantes.push(m);
}

// últimas 30
const ultimas = relevantes.slice(-30);

// helper: uma linha só (evita quebrar prompt)
const oneLine = (s) => String(s ?? '')
  .replace(/\r\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n') // compacta excessos
  .trim();

const linhas = [];
for (const m of ultimas) {
  const senderType = (m?.sender?.type ?? '').toLowerCase(); // contact | user | agent_bot
  const isPrivate = m?.private === true;
  const isBot = senderType === 'agent_bot';

  let autor;
  if (isBot) autor = isPrivate ? '[Sistema]' : '[Clara]';
  else if (senderType === 'contact') autor = '[Cliente]';
  else if (senderType === 'user') autor = isPrivate ? '[Interno]' : '[Atendente]';
  else autor = '[Sistema]';

  // conteúdo
  let texto = '';
  const content = (m?.content ?? '').trim();
  if (content) {
    texto = oneLine(content);
  } else if (m?.attachments?.length) {
    texto = '[Anexo]';
  } else {
    continue;
  }

  const privTag = (isPrivate && !isBot) ? ' (privado)' : '';
  linhas.push(`${autor}${privTag}: ${texto}`);
}

// monta histórico
let historico = linhas.join('\n');

// corta histórico se ficar grande (evita lentidão / token)
const MAX_CHARS = 6000;
if (historico.length > MAX_CHARS) {
  historico = historico.slice(-MAX_CHARS);
}

// pega pergunta atual do Normalizar (com first)
const norm = $('Normalizar').first()?.json ?? {};
const texto_atual = String(norm.texto || '').trim();
const nome_atendente = String(norm.nome_atendente || 'Atendente');

const prompt_copiloto = `${historico}\n\n---\nPergunta de ${nome_atendente}: ${texto_atual}`;

return [{
  json: {
    historico,
    prompt_copiloto,
    total_mensagens: ultimas.length,
  }
}];

// ============================================================
// PREPARAR ROTA FINAL — Code Node (n8n)
// Projeto Tozi Imobiliária
// Unifica saída de mídia processada e fallback
// Roda ANTES do Switch Rota Final
// ============================================================

const normalizar = $('Normalizar').first().json;

let texto_para_agente;

try {
  // Se passou por processamento (audio/imagem), pega texto_final
  texto_para_agente = $('Formatar Mídia').first().json.texto_final;
} catch (e) {
  // Se veio do fallback (contato, localização, vídeo, documento, sticker)
  texto_para_agente = normalizar.texto_humano;
}

return {
  json: {
    texto_para_agente,
    rota_final: normalizar.rota_final,
    conversa_id: normalizar.conversa_id,
    contato_id: normalizar.contato_id,
    nome_cliente: normalizar.nome_cliente,
    tipo_conteudo: normalizar.tipo_conteudo,
  }
};

// ============================================================
// FORMATAR MÍDIA v2 — Code Node (n8n)
// Projeto Tozi Imobiliária
// Roda DEPOIS do processamento (transcrição, análise)
// e ANTES do HTTP Request da nota privada
// ============================================================
const normalizar = $('Normalizar').first().json;
const tipo = normalizar.tipo_conteudo;
const legenda = normalizar.legenda || null;
const autor_legivel = normalizar.autor === 'cliente' ? 'cliente' : 'atendente';

const input = $input.first().json;

let mensagem = '';
let texto_processado = '';

if (tipo === 'audio') {
  const transcricao = input.text || '[Transcrição indisponível]';
  const duracao = input.usage?.seconds ? ` (${input.usage.seconds}s)` : '';
  texto_processado = transcricao;
  mensagem = `📎 Transcrição de áudio do ${autor_legivel}${duracao}:\n\n${transcricao}`;

} else if (tipo === 'imagem') {
  const descricao = input.content || input.text || '[Descrição indisponível]';
  texto_processado = descricao;
  mensagem = `📎 Descrição de imagem do ${autor_legivel}:\n\n${descricao}`;
  if (legenda) {
    mensagem += `\nLegenda: ${legenda}`;
    texto_processado += `\nLegenda: ${legenda}`;
  }

} else {
  texto_processado = normalizar.texto_humano;
  mensagem = `📎 ${texto_processado}`;
}

return {
  json: {
    mensagem,
    texto_final: texto_processado,
    tipo_conteudo: tipo,
    rota_final: normalizar.rota_final,
    conversa_id: normalizar.conversa_id,
  }
};

