## Data e hora

{{
  (() => {
    const now = DateTime.now();
    const fmtNow = 'dd/LL/yyyy HH:mm:ss';
    const MIN = (h, m) => h * 60 + m;

    const schedule = {
      1: [[MIN(7,30), MIN(11,30)], [MIN(13,30), MIN(17,30)]],
      2: [[MIN(7,30), MIN(11,30)], [MIN(13,30), MIN(17,30)]],
      3: [[MIN(7,30), MIN(11,30)], [MIN(13,30), MIN(17,30)]],
      4: [[MIN(7,30), MIN(11,30)], [MIN(13,30), MIN(17,30)]],
      5: [[MIN(7,30), MIN(11,30)], [MIN(13,30), MIN(17,30)]],
      6: [[MIN(9,0),  MIN(11,30)]],
      7: []
    };

    const weekdayName = (w) => ({1:'Segunda',2:'Terça',3:'Quarta',4:'Quinta',5:'Sexta',6:'Sábado',7:'Domingo'})[w] || '';

    const minutesNow = now.hour * 60 + now.minute;
    const todaysIntervals = schedule[now.weekday] || [];
    const isOpenNow = todaysIntervals.some(([start, end]) => minutesNow >= start && minutesNow < end);

    const makeDateTimeAt = (baseDay, startMin) => {
      const h = Math.floor(startMin / 60);
      const m = startMin % 60;
      return baseDay.set({ hour: h, minute: m, second: 0, millisecond: 0 });
    };

    const findNextOpening = () => {
      for (const [start] of todaysIntervals) {
        if (minutesNow < start) return makeDateTimeAt(now, start);
      }
      for (let i = 1; i <= 14; i++) {
        const day = now.plus({ days: i }).startOf('day');
        const intervals = schedule[day.weekday] || [];
        if (intervals.length > 0) return makeDateTimeAt(day, intervals[0][0]);
      }
      return null;
    };

    const nextOpening = isOpenNow ? (() => {
      for (const [start, end] of todaysIntervals) {
        if (minutesNow >= start && minutesNow < end) {
          const idx = todaysIntervals.findIndex(i => i[0] === start && i[1] === end);
          const nextToday = todaysIntervals[idx + 1]?.[0];
          if (nextToday != null) return makeDateTimeAt(now, nextToday);
          return findNextOpening();
        }
      }
      return findNextOpening();
    })() : findNextOpening();

    const formatNextHuman = (dt) => {
      if (!dt) return '';
      const timeStr = dt.toFormat('HH:mm');
      const today = now.startOf('day');
      const tomorrow = today.plus({ days: 1 });
      if (dt.hasSame(today, 'day')) return `hoje às ${timeStr}`;
      if (dt.hasSame(tomorrow, 'day')) return `amanhã às ${timeStr}`;
      return `${weekdayName(dt.weekday)} às ${timeStr}`;
    };

    const statusLine = isOpenNow ? '✅ Dentro do horário' : '⛔ Fora do horário';
    const lines = [`Agora: ${now.toFormat(fmtNow)}`, statusLine];
    if (!isOpenNow) lines.push(`Próximo: ${formatNextHuman(nextOpening)}`);
    return lines.join('\n');
  })()
}}

